pub fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    if n == 0 {
        return Vec::new();
    }

    // Result size is exactly 2n - 1 when n > 0.
    let mut res = Vec::with_capacity(2 * n - 1);

    // Push first element, then (delim, element) pairs for the rest.
    res.push(numbers[0]);
    for &x in &numbers[1..] {
        res.push(delim);
        res.push(x);
    }

    res
}